{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--glass:rgba(255,255,255,0.06);--accent:#6fb3c8;--muted:#bfc9d2;--card:#0b1320}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#eef2f7;background:linear-gradient(180deg,#071124 0%, #0b2433 100%);-webkit-font-smoothing:antialiased}
    .wrap{min-height:100%;display:flex;flex-direction:column}
    header{backdrop-filter:blur(8px);background:linear-gradient(90deg,rgba(255,255,255,0.03),transparent);padding:18px 24px;border-bottom:1px solid rgba(255,255,255,0.03)}
    nav{display:flex;gap:18px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
    .logo{font-weight:700;color:#fff;margin-right:12px}
    main{flex:1;display:flex;flex-direction:column;gap:28px;padding:36px;align-items:center}
    .hero{width:100%;max-width:980px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;padding:28px;box-shadow:0 6px 30px rgba(2,6,23,0.6);display:grid;grid-template-columns:1fr 320px;gap:20px}
    .hero h1{margin:0;font-size:22px;color:#fff}
    .hero p{color:var(--muted);line-height:1.5;margin-top:8px}
    .cta{margin-top:18px}
    .btn{background:linear-gradient(135deg,var(--accent),#84c7d8);border:none;padding:10px 16px;border-radius:10px;color:#072028;font-weight:700;cursor:pointer}
    .profile{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px}
    .meta{color:var(--muted);font-size:13px;margin-top:10px}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
    .card{background:var(--glass);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    .card h4{margin:0;color:#eaf6fb;font-size:13px}
    .card p{margin:6px 0 0 0;color:var(--muted);font-size:13px}

    /* Proof Gallery */
    .proof{margin-top:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:12px;border-radius:12px}
    .rotator{position:relative;min-height:110px}
    .quote{position:absolute;inset:0;opacity:0;transform:translateY(8px);transition:opacity .5s,transform .5s;color:var(--muted)}
    .quote.active{opacity:1;transform:none}
    .badges{display:flex;gap:8px;margin-top:10px}
    .badge{padding:6px 8px;border-radius:8px;background:rgba(255,255,255,0.02);display:flex;align-items:center;gap:8px;font-size:13px;color:var(--muted);cursor:default;position:relative}
    .badge svg{width:18px;height:18px;opacity:0.92}
    .tooltip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);padding:8px 10px;background:#071122;color:#cfeef6;border-radius:8px;font-size:12px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .18s}
    .badge:hover .tooltip{opacity:1}

    /* small fine print */
    .footnote{color:var(--muted);font-size:13px;max-width:820px}
    footer{padding:22px 36px;border-top:1px solid rgba(255,255,255,0.02);color:var(--muted);font-size:13px}

    /* decorative pattern */
    .pattern{position:absolute;right:20px;top:20px;opacity:0.08;pointer-events:none}

    @media(max-width:880px){.hero{grid-template-columns:1fr;padding:18px}.grid{grid-template-columns:repeat(2,1fr)}nav{flex-wrap:wrap}}
    @media(max-width:520px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <nav>
        <div class="logo">{{BUSINESS_NAME}}</div>
        <a href="index.html">Start</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Services</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Rates</a>
        <a href="faq.html">Help</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <section class="hero" aria-labelledby="about-header">
        <div>
          <h1 id="about-header">I work with adults facing transitions, uncertainty, and recurring patterns.</h1>
          <p>I offer structured clinical care with pragmatic goals — a steady place to sort priorities, discover patterns that limit you, and practice different choices. Sessions are collaborative and tailored: we set aims together and revisit them as life shifts.</p>
          <div class="cta">
            <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="proof" aria-live="polite">
            <strong style="color:#e8fbff">What people say</strong>
            <div class="rotator" id="rotator">
              <div class="quote active">"Clear, practical steps helped me manage uncertainty without avoiding it. I left sessions with a plan I could use the next day." — L., client</div>
              <div class="quote">"Warm, focused sessions that respected my pace and kept me accountable to small changes." — R., client</div>
              <div class="quote">"Clinical, calm, and very human. The structure made hard changes feel possible." — K., client</div>
            </div>
            <div class="badges" aria-hidden="false">
              <div class="badge" tabindex="0">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" stroke="#84c7d8" stroke-width="1.6"/><path d="M8 12.5l2.4 2.2L16 9" stroke="#84c7d8" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
                Licensed
                <div class="tooltip">State-licensed clinician — scope and credentialing apply</div>
              </div>
              <div class="badge" tabindex="0">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" stroke="#6fb3c8" stroke-width="1.6"/><path d="M7 12h10" stroke="#6fb3c8" stroke-width="1.6" stroke-linecap="round"/></svg>
                HIPAA-aware
                <div class="tooltip">Confidential clinical record practice and secure correspondence</div>
              </div>
              <div class="badge" tabindex="0">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 5v14" stroke="#99d7e2" stroke-width="1.6" stroke-linecap="round"/><path d="M5 12h14" stroke="#99d7e2" stroke-width="1.6" stroke-linecap="round"/></svg>
                Continuing Education
                <div class="tooltip">Ongoing training in evidence-informed methods</div>
              </div>
            </div>
          </div>

        </div>
        <aside class="profile">
          <div style="display:flex;align-items:center;gap:12px">
            <div style="width:72px;height:72px;border-radius:12px;background:linear-gradient(180deg,#12313c,#0b1c22);display:flex;align-items:center;justify-content:center;color:#cfeef6;font-weight:700">MH</div>
            <div>
              <div style="font-weight:700;color:#eaf6fb">Clinician, Licensed Psychotherapist</div>
              <div class="meta">Private practice in {{CITY}}, {{STATE}} • Sessions by telehealth and limited in-person</div>
            </div>
          </div>

          <div class="grid">
            <div class="card"><h4>Training</h4><p>Graduate clinical training with ongoing supervision and specialty coursework</p></div>
            <div class="card"><h4>Approach</h4><p>Beat-by-beat planning, skill practice, and attention to meaning in daily life</p></div>
            <div class="card"><h4>Availability</h4><p>Weekday and limited evening slots. Email for current openings.</p></div>
          </div>

          <p class="meta" style="margin-top:12px">Phone: <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a></p>
        </aside>
      </section>

      <section style="max-width:980px;text-align:left">
        <h3 style="color:#eaf6fb">A note on confidentiality and boundaries</h3>
        <p class="footnote">Clinical notes and communications are kept private in line with professional standards and record-keeping practices. Therapy supports many kinds of life change but is not an emergency service — if you are in crisis or risk of harm, contact emergency services or your local crisis line right away. If you have questions about whether therapy is a right fit, we can discuss scope and referrals during an initial conversation.</p>
      </section>

    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;max-width:980px;margin:0 auto">
        <div>© <span id="year"></span> {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
        <div style="color:var(--muted)">Made with care • Clinical, calm, and pragmatic support</div>
      </div>
    </footer>
  </div>

  <svg class="pattern" width="220" height="220" viewBox="0 0 220 220" aria-hidden="true"><defs><pattern id="p" width="28" height="28" patternUnits="userSpaceOnUse" patternTransform="rotate(18)"><rect width="28" height="28" fill="none"/><path d="M0 14h28M14 0v28" stroke="#9fdbe6" stroke-opacity="0.06" stroke-width="1"/></pattern></defs><rect width="220" height="220" fill="url(#p)" rx="24"/></svg>

  <script>
    // Year
    document.getElementById('year').textContent = new Date().getFullYear();

    // Proof rotator
    (function(){
      const rotator = document.getElementById('rotator');
      const quotes = Array.from(rotator.children);
      let idx = 0; let interval = 6000;
      function show(i){
        quotes.forEach((q,ii)=>{q.classList.toggle('active', ii===i)});
      }
      let timer = setInterval(()=>{ idx=(idx+1)%quotes.length; show(idx); }, interval);
      // pause on hover
      rotator.addEventListener('mouseenter', ()=>clearInterval(timer));
      rotator.addEventListener('mouseleave', ()=>{ timer = setInterval(()=>{ idx=(idx+1)%quotes.length; show(idx); }, interval); });
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Services & Specialties — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#08121a;--glass:rgba(255,255,255,0.04);--accent:#78c2c9;--muted:#b9c6ce}
    body{margin:0;background:linear-gradient(180deg,#061016,#071521);font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#eaf6fb}
    header{padding:18px 26px;backdrop-filter:blur(6px);border-bottom:1px solid rgba(255,255,255,0.03)}
    nav{display:flex;gap:18px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;font-size:14px}
    .logo{font-weight:700;color:#fff;margin-right:12px}
    main{padding:30px;display:flex;flex-direction:column;gap:18px;align-items:center}
    .panel{width:100%;max-width:980px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;padding:20px;box-shadow:0 6px 30px rgba(0,0,0,0.6)}
