    .service p{color:var(--muted);font-size:14px;margin-top:8px}

    /* Pricing comparator */
    .pricing{display:flex;gap:12px;align-items:center;margin-top:18px}
    .toggle{display:flex;gap:6px;align-items:center;background:rgba(255,255,255,0.02);padding:6px;border-radius:999px}
    .toggle button{background:none;border:none;padding:8px 12px;border-radius:999px;color:var(--muted);cursor:pointer;font-weight:700}
    .toggle button.active{background:linear-gradient(135deg,var(--accent),#9fdbe6);color:#052025}
    .priceCard{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);width:220px}
    .price{font-size:26px;font-weight:800;color:#dff8fb}
    .sub{color:var(--muted);font-size:13px}
